/*
 * AST_$ACTIVATE_ASTE_CANNED - Activate one segment of a well-known object
 *
 * Original address: 0x00E2F1D4 (SAU2 map: AST_$ACTIVATE_ASTE_CANNED)
 * Size: 462 bytes (0x00E2F1D4 .. 0x00E2F3A3); its crash status follows at
 * 0x00E2F3A4.
 * Generated by: Claude Opus 5.5 (reviewed by Claude Fable 5.1)
 *
 * Boot-time companion of AST_$ACTIVATE_AOTE_CANNED: under the AST lock,
 * find the AOTE of `uid' and return an ASTE for segment `seg' with one more
 * reference.  A UID whose first byte is zero (the canned objects) gets a
 * fresh ASTE threaded into the AOTE's segment list with every page of its
 * segment map "no disk block" (0x3FFFFF) and copy-on-write; any other UID
 * goes through the ordinary lookup / lookup-or-create path.
 *
 * Frame (link.w A6,-0x18; D2-D3/A2-A5 saved; A5 = 0xE35004, the init
 * segment's base, loaded but never used - AST_$DATA is addressed
 * absolutely, `movea.l #0xe1dc80,A0`):
 *   (0x08,A6) uid (A2)     (0x0C,A6) seg word (D2w)
 *   (-0x04,A6) status for ast_$lookup_or_create_aste
 *
 * Blocks:
 *   0x00E2F1E6-0x00E2F214  ML_$LOCK(AST); the AOTE (none: crash)
 *   0x00E2F216-0x00E2F21C  first UID byte zero: canned path
 *   0x00E2F220-0x00E2F280  a fresh ASTE: flags bits 15..12 clear, bit 11
 *                          (remote) from the AOTE's remote byte, counted in
 *                          AST_$ASTE_R_CNT / AST_$ASTE_L_CNT; no pages,
 *                          one reference, owner, segment
 *   0x00E2F282-0x00E2F2C4  thread it into aote->aste_list
 *   0x00E2F2C6-0x00E2F348  count it on the AOTE; its 32 segment-map
 *                          entries: bits 31..23 clear, bit 22 set, low 22
 *                          bits all ones
 *   0x00E2F34A-0x00E2F388  otherwise ast_$lookup_aste, then
 *                          ast_$lookup_or_create_aste (failure: crash with
 *                          its status); one more reference
 *   0x00E2F38C-0x00E2F3A2  ML_$UNLOCK(AST); the ASTE in A0
 *
 * Quirks reproduced:
 *   - The fresh ASTE's wire_count is set to 1 and is not incremented again
 *     (the other path increments, 0x00E2F388).
 *   - The list is kept in descending segment order only at its head: a
 *     segment above the head's goes before it, one below or equal to it
 *     enters the walk (`cmp.w (0xc,A4),D2w; bls` 0x00E2F28C-0x00E2F290,
 *     unsigned), where an equal segment crashes.  Past the head the walk
 *     stops at the first entry whose successor is NOT nil (`tst.l (A4);
 *     bne` 0x00E2F2A2).  When the successor is nil the walk reads the
 *     segment word of the nil ASTE (`movea.l (A4),A0; cmp.w (0xc,A0),D2w`
 *     0x00E2F2A6), i.e. the word at address 0x0C, and may make nil the
 *     current entry.  A duplicate segment crashes and the walk would resume
 *     at the same entry (0x00E2F2C4 `bra 0x00E2F29C`).
 *   - `subq.l #2,SP' before ML_$LOCK and ML_$UNLOCK reserves slots no one
 *     reads (0x00E2F1E6, 0x00E2F38C).
 */

#include "ast/ast_internal.h"
#include "misc/misc.h"
#include "ml/ml.h"
#include "pmap/pmap.h"

/*
 * `pea (0x198,PC)` at 0x00E2F20A and `pea (0xea,PC)` at 0x00E2F2B8 both
 * reach 0x00E2F3A4, bytes 00 03 00 01.
 */
static const status_$t ast_$activate_aste_canned_crash = status_$ast_eof;

/* `andi.w #-0x1f81` on the entry's high word clears longword bits 28..23 */
#define AST_CANNED_SEGMAP_CLEAR_28_23   0x1F800000u
#define AST_CANNED_SEGMAP_COW           0x00400000u   /* ori.w #0x40, high word */
#define AST_CANNED_SEGMAP_NO_BLOCK      0x003FFFFFu   /* ori.l #0x3fffff */

aste_t *AST_$ACTIVATE_ASTE_CANNED(uid_t *uid, uint16_t seg)
{
    status_$t status;                   /* (-0x04,A6) */
    aote_t *aote;                       /* A3 */
    aste_t *aste;                       /* A2 */
    aste_t *cur;                        /* A4 */
    aste_t *volatile nxt;               /* A0: reloaded, may be nil */
    uint32_t *segmap;
    int16_t i;                          /* D0w, moveq #0x1f / dbf */
    int16_t k;                          /* D1 / 4 */

    /* 0x00E2F1E6-0x00E2F214 */
    ML_$LOCK(AST_LOCK_ID);
    aote = ast_$lookup_aote_by_uid(uid);
    if (aote == NULL) {
        CRASH_SYSTEM(&ast_$activate_aste_canned_crash);
    }

    if (((uid->high >> 24) & 0xFF) == 0) {
        /* 0x00E2F220-0x00E2F280 */
        aste = AST_$ALLOCATE_ASTE();
        aste->flags &= (uint16_t)~ASTE_FLAG_IN_TRANS;      /* bclr.b #7 */
        aste->flags &= (uint16_t)~ASTE_FLAG_LOCKED;        /* bclr.b #6 */
        aste->flags &= (uint16_t)~ASTE_FLAG_DIRTY;         /* bclr.b #5 */
        aste->flags &= (uint16_t)~ASTE_FLAG_AREA;          /* bclr.b #4 */
        aste->flags &= (uint16_t)~ASTE_FLAG_REMOTE;        /* andi.b #-0x9 */
        if (aote->remote_flag < 0) {                      /* smi / lsl.b #3 */
            aste->flags |= ASTE_FLAG_REMOTE;
        }
        if (aote->remote_flag < 0) {
            AST_$ASTE_R_CNT++;
        } else {
            AST_$ASTE_L_CNT++;
        }
        aste->page_count = 0;
        aste->wire_count = 1;
        aste->aote = aote;
        aste->segment = seg;

        /* 0x00E2F282-0x00E2F2C4 */
        cur = aote->aste_list;
        if (cur == NULL || seg > cur->segment) {   /* bls = seg <= head: walk */
            aote->aste_list = aste;
            aste->next = cur;
        } else {
            for (;;) {
                if (seg == cur->segment) {
                    CRASH_SYSTEM(&ast_$activate_aste_canned_crash);
                    continue;
                }
                if (cur->next != NULL) {
                    break;
                }
                /* the successor is nil here; the image still reads its
                 * segment word (address 0x0C).  `nxt' is volatile so the
                 * compiler cannot fold the known-nil load and replace the
                 * read with a trap (-fisolate-erroneous-paths-dereference at
                 * -O2); the read itself is modelled as the image does it */
                nxt = cur->next;
                if (seg >= nxt->segment) {
                    break;
                }
                cur = nxt;
            }
            aste->next = cur->next;
            cur->next = aste;
        }

        /* 0x00E2F2C6-0x00E2F348 */
        aote->status_flags++;
        segmap = (uint32_t *)(void *)PMAP_SEGMAP_ROW(aste->seg_index);
        k = 0;
        for (i = 0x1F; i >= 0; i--) {
            segmap[k] &= ~0x20000000u;                     /* bclr.b #0xd */
            segmap[k] &= ~0x80000000u;                     /* bclr.b #0xf */
            segmap[k] &= ~0x40000000u;                     /* bclr.b #0xe */
            segmap[k] &= ~AST_CANNED_SEGMAP_CLEAR_28_23;
            segmap[k] |= AST_CANNED_SEGMAP_COW;
            segmap[k] |= AST_CANNED_SEGMAP_NO_BLOCK;
            k++;
        }
    } else {
        /* 0x00E2F34A-0x00E2F388 */
        aste = ast_$lookup_aste(aote, (int16_t)seg);
        if (aste == NULL) {
            aste = ast_$lookup_or_create_aste(aote, seg, &status);
            if (aste == NULL) {
                CRASH_SYSTEM(&status);
            }
        }
        aste->wire_count++;
    }

    /* 0x00E2F38C-0x00E2F3A2 */
    ML_$UNLOCK(AST_LOCK_ID);
    return aste;
}
